        '.dsh-editor-stripe-item:hover { background: var(--dsw-alias-interactive-bg-hover); }',
        '.dsh-editor-stripe-close:focus-visible {',
        '  outline: 1px solid var(--dsw-alias-state-business-primary) !important;',
